import { auth } from '@/lib/auth';
import { redirect } from 'next/navigation';
import { prisma } from '@/lib/prisma';
import { StatsCard } from '@/components/ui/stats-card';
import { BillingPageClient } from '@/components/dashboard/billing-page-client';
import { formatMoney } from '@/lib/utils';

export default async function BillingPage() {
  const session = await auth();
  if (!session) redirect('/login');

  const userId = session.user.id;
  const now = new Date();
  const periodStart = new Date(now.getFullYear(), now.getMonth(), 1);

  // Fetch user agents for rate table
  const userAgents = await prisma.userAgent.findMany({
    where: { userId },
    include: { agent: { select: { name: true, retellAgentId: true } } },
    orderBy: { assignedAt: 'desc' },
  });

  // Calculate current month usage per agent
  const agentSummaries = await Promise.all(
    userAgents.map(async (ua) => {
      const effectiveStart = ua.assignedAt > periodStart ? ua.assignedAt : periodStart;
      const result = await prisma.call.aggregate({
        _sum: { durationMs: true },
        where: {
          agentId: ua.agent.retellAgentId,
          startTimestamp: { gte: effectiveStart, lt: now },
        },
      });
      const totalMs = result._sum.durationMs ?? 0;
      const minutesUsed = Math.round((totalMs / 60000) * 100) / 100;
      const customPriceNum = ua.customPrice ? Number(ua.customPrice) : null;
      const usageCost = customPriceNum != null ? Math.round(minutesUsed * customPriceNum * 100) / 100 : null;

      return {
        agentName: ua.agent.name,
        minutesUsed,
        usageCost,
        monthlyFee: ua.monthlyFee ? Number(ua.monthlyFee) : null,
        customPrice: customPriceNum,
        setupFee: ua.setupFee ? Number(ua.setupFee) : null,
        setupFeePaid: ua.setupFeePaid,
      };
    })
  );

  const totalMinutes = agentSummaries.reduce((s, a) => s + a.minutesUsed, 0);
  const estimatedBill = agentSummaries.reduce(
    (s, a) => s + (a.usageCost ?? 0) + (a.monthlyFee ?? 0),
    0
  );

  // Fetch invoices
  const invoicesRaw = await prisma.invoice.findMany({
    where: { userId },
    orderBy: { createdAt: 'desc' },
    include: { _count: { select: { lineItems: true } } },
  });

  const pendingCount = invoicesRaw.filter(i => ['PENDING', 'OVERDUE'].includes(i.status)).length;

  const invoices = invoicesRaw.map(inv => ({
    id: inv.id,
    invoiceNumber: inv.invoiceNumber,
    periodStart: inv.periodStart.toISOString(),
    periodEnd: inv.periodEnd.toISOString(),
    status: inv.status as 'DRAFT' | 'PENDING' | 'PAID' | 'OVERDUE' | 'CANCELLED',
    subtotal: Number(inv.subtotal),
    total: Number(inv.total),
    paidAt: inv.paidAt?.toISOString() ?? null,
    createdAt: inv.createdAt.toISOString(),
    lineItemsCount: inv._count.lineItems,
  }));

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Billing</h1>
        <p className="text-gray-500 mt-1">Track your usage and invoices</p>
      </div>

      {/* Current Month Summary */}
      <section className="space-y-3">
        <h2 className="text-sm font-semibold text-gray-700 uppercase tracking-wide">Current Month</h2>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <StatsCard
            title="Minutes Used"
            value={`${Math.round(totalMinutes * 100) / 100} min`}
            subtitle={`${now.toLocaleString('default', { month: 'long' })} so far`}
            icon="clock"
          />
          <StatsCard
            title="Estimated Bill"
            value={formatMoney(Math.round(estimatedBill * 100) / 100)}
            subtitle="Usage + monthly fees"
            icon="dollar-sign"
          />
          <StatsCard
            title="Invoices Pending"
            value={pendingCount}
            subtitle="Awaiting payment"
            icon="alert-circle"
            iconColor={pendingCount > 0 ? 'text-yellow-500' : 'text-[#004D3E]'}
          />
        </div>
      </section>

      {/* Agent Fee Summary */}
      {userAgents.length > 0 && (
        <section className="space-y-3">
          <h2 className="text-sm font-semibold text-gray-700 uppercase tracking-wide">Your Agents</h2>
          <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-100 bg-gray-50">
                  <th className="text-left px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Agent</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Setup Fee</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Monthly Fee</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Per-Min Rate</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Min Used (This Month)</th>
                  <th className="text-right px-4 py-3 text-xs font-medium text-gray-500 uppercase tracking-wide">Est. Usage Cost</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {agentSummaries.map(a => (
                  <tr key={a.agentName} className="hover:bg-gray-50">
                    <td className="px-4 py-3 font-medium text-gray-900">{a.agentName}</td>
                    <td className="px-4 py-3 text-right">
                      {a.setupFee != null ? (
                        <span className="text-gray-600">
                          {formatMoney(a.setupFee)}
                          {' '}
                          <span className={`text-xs font-medium ${a.setupFeePaid ? 'text-green-600' : 'text-yellow-600'}`}>
                            ({a.setupFeePaid ? 'paid' : 'pending'})
                          </span>
                        </span>
                      ) : (
                        <span className="text-gray-400">—</span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-right text-gray-600">{formatMoney(a.monthlyFee)}</td>
                    <td className="px-4 py-3 text-right text-gray-600">
                      {a.customPrice != null ? `$${a.customPrice.toFixed(4)}/min` : '—'}
                    </td>
                    <td className="px-4 py-3 text-right text-gray-600">{a.minutesUsed}</td>
                    <td className="px-4 py-3 text-right font-medium">{formatMoney(a.usageCost)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}

      {/* Invoice History */}
      <section className="space-y-3">
        <h2 className="text-sm font-semibold text-gray-700 uppercase tracking-wide">Invoice History</h2>
        <BillingPageClient invoices={invoices} />
      </section>
    </div>
  );
}
